// === Tab: mySketch.js ===
let palette = ['#77b9d4', '#375399', '#ffffff'];
let vmin, vmax;
let ctx;
let glsl, pgScale = 10;
let triUvTex, triStrokeTex;
let NUM = 12, step, radius;
let triArr = [];

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1492208/files/shader.vert', 'shader.frag');
}

function setup() {
  pixelDensity(2);
  createCanvas(1112, 834, WEBGL);
  vmin = max(width, height);
  vmax = max(width, height);
  let fov = PI * 0.4;
  let eyeZ = (height / 2) / tan(fov / 2);
  triUvTex = createGraphics(width, height);
  triStrokeTex = createGraphics(width, height);

  step = vmax / (NUM - 1);
  radius = (step / 2) / (3 / 2);

  let r = radius;
  for (let l = 0; l <= NUM + 1; l++) {
    let y = l * (r * 3 * cos(PI / 6));
    for (let k = 0; k < NUM; k++) {
      let x = k * step;
      if (l % 2 === 1) {
        x += step / 2;
      }
      for (let j = 0; j < 6; j++) {
        let A = j * TWO_PI / 6;
        let cx = x + cos(A) * r;
        let cy = y + sin(A) * r;
        for (let i = 0; i < 3; i++) {
          let i2 = (i + 1) % 3;
          let a1 = i * TWO_PI / 3 + A + PI;
          let v1 = createVector(cx + cos(a1) * r, cy + sin(a1) * r);
          let a2 = i2 * TWO_PI / 3 + A + PI;
          let v2 = createVector(cx + cos(a2) * r, cy + sin(a2) * r);
          triArr.push({
            v0: createVector(cx, cy),
            v1,
            v2
          });
        }
      }
    }
  }

  // uv texture
  for (let { v0, v1, v2 } of triArr) {
    let vx = (v0.x + v1.x + v2.x) / 3;
    let vy = (v0.y + v1.y + v2.y) / 3;
    let u = map(vx, 0, triUvTex.width, 0, 255);
    let v = map(vy, 0, triUvTex.height, 0, 255);
    triUvTex.fill(u, v, 0);
    triUvTex.stroke(u, v, 0);
    triUvTex.beginShape(TRIANGLES);
    triUvTex.vertex(v0.x, v0.y);
    triUvTex.vertex(v1.x, v1.y);
    triUvTex.vertex(v2.x, v2.y);
    triUvTex.endShape();
  }

  // stroke texture
  triStrokeTex.noFill();
  triStrokeTex.strokeWeight(0.1);
  triStrokeTex.stroke(palette[1]);
  for (let { v0, v1, v2 } of triArr) {
    var vx = (v0.x + v1.x + v2.x) / 3;
    var vy = (v0.y + v1.y + v2.y) / 3;
    triStrokeTex.beginShape(TRIANGLES);
    triStrokeTex.vertex(v0.x, v0.y);
    triStrokeTex.vertex(v1.x, v1.y);
    triStrokeTex.vertex(v2.x, v2.y);
    triStrokeTex.endShape();
  }
}

function draw() {
  let sec = millis() / 1000;

  background(palette[0]);

  noStroke();
  push();
  {
    shader(glsl);
    glsl.setUniform('uUvTex', triUvTex);
    glsl.setUniform('uColor0', color(palette[0])._array);
    glsl.setUniform('uColor1', color(palette[1])._array);
    glsl.setUniform('uColor2', color(palette[2])._array);
    glsl.setUniform('uTime', sec);
    plane(width, height);
  }
  pop();

  push();
  {
    texture(triStrokeTex);
    plane(width, height);
  }
  pop();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

// === Tab: shader.vert ===
attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 position = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * position;
}

// === Tab: shader.frag ===
precision mediump float;

varying vec2 vTexCoord;

uniform sampler2D uUvTex;
uniform vec4 uColor0;
uniform vec4 uColor1;
uniform vec4 uColor2;
uniform float uTime;

//
// Description : Array and textureless GLSL 2D/3D/4D simplex 
//               noise functions.
//      Author : Ian McEwan, Ashima Arts.
//  Maintainer : stegu
//     Lastmod : 20201014 (stegu)
//     License : Copyright (C) 2011 Ashima Arts. All rights reserved.
//               Distributed under the MIT License. See LICENSE file.
//               https://github.com/ashima/webgl-noise
//               https://github.com/stegu/webgl-noise
// 

vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 mod289(vec4 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 permute(vec4 x) {
     return mod289(((x*34.0)+10.0)*x);
}

vec4 taylorInvSqrt(vec4 r)
{
  return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec3 v)
  { 
  const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
  const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

// First corner
  vec3 i  = floor(v + dot(v, C.yyy) );
  vec3 x0 =   v - i + dot(i, C.xxx) ;

// Other corners
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min( g.xyz, l.zxy );
  vec3 i2 = max( g.xyz, l.zxy );

  //   x0 = x0 - 0.0 + 0.0 * C.xxx;
  //   x1 = x0 - i1  + 1.0 * C.xxx;
  //   x2 = x0 - i2  + 2.0 * C.xxx;
  //   x3 = x0 - 1.0 + 3.0 * C.xxx;
  vec3 x1 = x0 - i1 + C.xxx;
  vec3 x2 = x0 - i2 + C.yyy; // 2.0*C.x = 1/3 = C.y
  vec3 x3 = x0 - D.yyy;      // -1.0+3.0*C.x = -0.5 = -D.y

// Permutations
  i = mod289(i); 
  vec4 p = permute( permute( permute( 
             i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
           + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
           + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

// Gradients: 7x7 points over a square, mapped onto an octahedron.
// The ring size 17*17 = 289 is close to a multiple of 49 (49*6 = 294)
  float n_ = 0.142857142857; // 1.0/7.0
  vec3  ns = n_ * D.wyz - D.xzx;

  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);  //  mod(p,7*7)

  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_ );    // mod(j,N)

  vec4 x = x_ *ns.x + ns.yyyy;
  vec4 y = y_ *ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);

  vec4 b0 = vec4( x.xy, y.xy );
  vec4 b1 = vec4( x.zw, y.zw );

  //vec4 s0 = vec4(lessThan(b0,0.0))*2.0 - 1.0;
  //vec4 s1 = vec4(lessThan(b1,0.0))*2.0 - 1.0;
  vec4 s0 = floor(b0)*2.0 + 1.0;
  vec4 s1 = floor(b1)*2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));

  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

  vec3 p0 = vec3(a0.xy,h.x);
  vec3 p1 = vec3(a0.zw,h.y);
  vec3 p2 = vec3(a1.xy,h.z);
  vec3 p3 = vec3(a1.zw,h.w);

//Normalise gradients
  vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
  p0 *= norm.x;
  p1 *= norm.y;
  p2 *= norm.z;
  p3 *= norm.w;

// Mix final noise value
  vec4 m = max(0.5 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
  m = m * m;
  return 105.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), 
                                dot(p2,x2), dot(p3,x3) ) );
}

void main() {
  vec2 uv = texture2D(uUvTex, vTexCoord).xy;

  float n0 = snoise(vec3(uv * vec2(2., 8) + vec2(uTime * 0.1, 0), uTime * 0.05)) * 0.5 + 0.5;
  float n1 = snoise(vec3(uv * vec2(0.25, 2) + vec2(uTime * 0.2, 0), uTime * 0.05)) * 0.5 + 0.5;
  float mask = n0 + n1;
  mask *= 1. - uv.y;
  mask = floor(mask * 5.) / 5.;

  vec3 color = mix(uColor0.rgb, uColor1.rgb, uv.y);
  color = mix(color, uColor2.rgb, mask);

  gl_FragColor = vec4(color, 1.0);
}

